import React,{useEffect,useMemo,useState} from 'react';
import {approvedReceipt} from './approvedReceipt.mjs';
import {readPrintPreferences,savePrintPreference} from './printPreferences.mjs';
import './windows-receipt-preview.css';

// The preview is generated by the same thermal text renderer that the print
// bridge uses. It contains only fictional data and never sends a print job.
const sample={
 source:'ifood',display_number:'3497',created_at:'17/11/2026 16:00',
 customer_name:'Cliente de exemplo',phone:'(21) 99999-9999',
 address:'Rua de Exemplo, 100 - Centro',reference:'Casa de portão branco',
 subtotal:21,delivery_fee:5,discount:0,total:26,payment_method:'Cartão',
 payment_status:'paid',notes:'Entregar na portaria',
 items:[
  {name:'Açaí 500 ml',quantity:1,total:15,modifiers:[
   {name:'Leite em pó',quantity:1},{name:'Morango',quantity:2}]},
  {name:'Açaí combo',quantity:1,total:6,modifiers:[
   {name:'Granola',quantity:1},{name:'Nutella',quantity:1}],notes:'Pouco gelo'}
 ]
};
const switches=[
 ['address','Endereço do cliente'],
 ['phone','Telefone do cliente'],
 ['notes','Observações'],
 ['complements','Complementos e quantidades']
];
export default function WindowsReceiptPreview({storeId,storeName='',initialWidth=80}){
 const [paperWidth,setPaperWidth]=useState(initialWidth===58?58:80);
 const [preferences,setPreferences]=useState(()=>readPrintPreferences(storeId));
 const [feedback,setFeedback]=useState('');
 useEffect(()=>{setPreferences(readPrintPreferences(storeId));setFeedback('');},[storeId]);
 useEffect(()=>{setPaperWidth(initialWidth===58?58:80);},[initialWidth]);
 const printed=useMemo(()=>approvedReceipt(
  {order_id:'3497',receipt:sample},paperWidth,{...preferences,storeName}
 ),[paperWidth,preferences,storeName]);
 function toggle(field,checked){
  if(savePrintPreference(storeId,field,checked)){
   setPreferences(readPrintPreferences(storeId));
   setFeedback('Preferência salva para esta loja neste computador.');
  }else setFeedback('Não foi possível salvar a preferência local.');
 }
 return <section className="panel pitacco-receipt-config" aria-label="Modelo de comanda e prévia térmica">
  <h3>Modelo de comanda e pré-visualização</h3>
  <p>Modelo padrão Pitacco baseado na nota aprovada, com seções e destaques como no exemplo da Brendi. O aplicativo envia texto térmico ESC/POS; a prévia usa exatamente o mesmo conteúdo, sem simular imagens que não serão impressas.</p>
  <div className="pitacco-receipt-workspace">
   <div className="pitacco-receipt-controls">
    <label className="field">Largura da prévia
     <select value={paperWidth} onChange={e=>setPaperWidth(Number(e.target.value))}>
      <option value={80}>80 mm</option><option value={58}>58 mm</option>
     </select>
    </label>
    <p>Conteúdo da nota</p>
    {switches.map(([field,label])=><label className="pitacco-receipt-switch" key={field}>
      <input type="checkbox" checked={preferences[field]!==false}
       onChange={e=>toggle(field,e.target.checked)}/>
      {label}
    </label>)}
    <p className="pitacco-receipt-help">As opções são exclusivas da loja atual. A prévia usa dados fictícios. A escolha da impressora, das vias e dos setores fica no cadastro de impressoras acima.</p>
    {feedback&&<p role="status">{feedback}</p>}
   </div>
   <div className="pitacco-receipt-paper-shell">
    <div className="pitacco-receipt-caption">Prévia da nota — {paperWidth} mm</div>
    <pre className={'pitacco-receipt-paper pitacco-receipt-paper--'+paperWidth}>{printed}</pre>
   </div>
  </div>
 </section>;
}
